import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../accounts_providers.dart';
class AccountsPolicyScreen extends ConsumerStatefulWidget{const AccountsPolicyScreen({super.key});@override ConsumerState<AccountsPolicyScreen> createState()=>_PolicyState();}class _PolicyState extends ConsumerState<AccountsPolicyScreen>{final max=TextEditingController(),before=TextEditingController();bool automatic=false,approval=true,saving=false;bool initialized=false;@override Widget build(BuildContext c){final q=ref.watch(accountsPolicyProvider);return Scaffold(appBar:AppBar(title:const Text('Collection policy')),body:q.when(loading:()=>const CircularProgressIndicator(),error:(e,_)=>Text('$e'),data:(p){if(!initialized){max.text='${p.max}';before.text='${p.before}';automatic=p.automatic;approval=p.approval;initialized=true;}return ListView(padding:const EdgeInsets.all(20),children:[TextField(controller:before,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Reminder before due (days)')),TextField(controller:max,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Maximum automatic reminders')),SwitchListTile(value:automatic,onChanged:(v)=>setState(()=>automatic=v),title:const Text('Automatic sending'),subtitle:const Text('Allow eligible reminders to be sent automatically.')),SwitchListTile(value:approval,onChanged:(v)=>setState(()=>approval=v),title:const Text('Approval required'),subtitle:const Text('Sensitive collection actions require a human decision.')),FilledButton(onPressed:saving?null:()async{setState(()=>saving=true);try{await ref.read(accountsRepositoryProvider).savePolicy({'reminder_before_due_days':int.tryParse(before.text)??p.before,'maximum_automatic_reminders':int.tryParse(max.text)??p.max,'automatic_sending_enabled':automatic,'final_demand_requires_approval':approval});ref.invalidate(accountsPolicyProvider);if(mounted)ScaffoldMessenger.of(c).showSnackBar(const SnackBar(content:Text('Policy saved')));}catch(_){if(mounted)ScaffoldMessenger.of(c).showSnackBar(const SnackBar(content:Text('Policy could not be saved')));}finally{if(mounted)setState(()=>saving=false);}},child:Text(saving?'Saving…':'Save policy'))]);}));}}
